edits.newText:
class VoidBrowserController {
  Future<void> Function(String path)? _scrollToTrack;
  bool Function(String path)? _isTrackVisible;

  final ValueNotifier<int> _visibilityTick = ValueNotifier(0);

  /// Centre the row for [path] in view; no-op when the browser is unmounted.
  Future<void> scrollToTrack(String path) async =>
      await _scrollToTrack?.call(path);

  /// Whether the browser can currently answer [isTrackVisible].
  bool get hasVisibilityProbe => _isTrackVisible != null;

  /// True when the row for [path] intersects the current browser viewport.
  ///
  /// Returns false when the browser is unmounted / cannot be probed.
  bool isTrackVisible(String path) => _isTrackVisible?.call(path) ?? false;

  /// Incremented on browser scroll/layout changes so callers can rebuild.
  ValueListenable<int> get visibilityTick => _visibilityTick;

  void _notifyVisibilityChanged() => _visibilityTick.value++;

  void dispose() => _visibilityTick.dispose();
}

